// Sprite atlas — loads atlas.png (generated by tools/atlas) once and
// extracts one SkImage per sprite frame (via offscreen surfaces), so the
// renderer draws sprites with plain <Image> nodes at 1:1 scale (crisp
// pixel art, no filtering artefacts). Returns null until loaded.

import { useEffect, useState } from 'react';
import { Skia, useImage, type SkImage } from '@shopify/react-native-skia';

import atlasManifest from '../../../assets/sprites/atlas.json';

export type AtlasImages = Record<string, SkImage>;

interface FrameRect {
  x: number;
  y: number;
  w: number;
  h: number;
}
interface AtlasManifest {
  tile: number;
  frames: Record<string, FrameRect>;
}
const manifest = atlasManifest as AtlasManifest;

export function useAtlas(): AtlasImages | null {
  const atlas = useImage(require('../../../assets/sprites/atlas.png'));
  const [images, setImages] = useState<AtlasImages | null>(null);

  useEffect(() => {
    if (!atlas) return;
    const out: AtlasImages = {};
    for (const [name, rect] of Object.entries(manifest.frames)) {
      const surface = Skia.Surface.MakeOffscreen(rect.w, rect.h);
      if (!surface) continue;
      const canvas = surface.getCanvas();
      canvas.drawImageRect(
        atlas,
        Skia.XYWHRect(rect.x, rect.y, rect.w, rect.h),
        Skia.XYWHRect(0, 0, rect.w, rect.h),
        Skia.Paint(),
      );
      const img = surface.makeImageSnapshot();
      if (img) out[name] = img;
      surface.dispose();
    }
    setImages(out);
    return () => {
      for (const img of Object.values(out)) img.dispose();
    };
  }, [atlas]);

  return images;
}
